import{_ as e,o as l,c as t,a4 as i}from"./chunks/framework.DzJZdBQK.js";const u=JSON.parse('{"title":"《定投改变命运》读书笔记","description":"","frontmatter":{"date":"2022-03-04T21:23:19","title":"《定投改变命运》读书笔记","categories":["写作","作业","定投","定投改变命运"],"tags":["写作","作业","定投","定投改变命运"]},"headers":[{"level":2,"title":"定投策略为什么有效？","slug":"定投策略为什么有效","link":"#定投策略为什么有效","children":[]},{"level":2,"title":"长期究竟有多长？","slug":"长期究竟有多长","link":"#长期究竟有多长","children":[]},{"level":2,"title":"为什么一定要用钱赚钱？","slug":"为什么一定要用钱赚钱","link":"#为什么一定要用钱赚钱","children":[]},{"level":2,"title":"我们到底在用什么定投？","slug":"我们到底在用什么定投","link":"#我们到底在用什么定投","children":[]},{"level":2,"title":"为什么定投策略无需再次改良？","slug":"为什么定投策略无需再次改良","link":"#为什么定投策略无需再次改良","children":[]},{"level":2,"title":"可以盲从的投资建议是什么？","slug":"可以盲从的投资建议是什么","link":"#可以盲从的投资建议是什么","children":[]},{"level":2,"title":"为什么趋势投资优于价值投资","slug":"为什么趋势投资优于价值投资","link":"#为什么趋势投资优于价值投资","children":[]},{"level":2,"title":"选择长期（两个大周期）定投的标的的方法论是什么？","slug":"选择长期-两个大周期-定投的标的的方法论是什么","link":"#选择长期-两个大周期-定投的标的的方法论是什么","children":[]},{"level":2,"title":"有的泡沫破裂之后，一蹶不振（郁金香泡沫），有的泡沫破裂之后，却逆势上扬（互联网，比特币泡沫）区别在哪里？","slug":"有的泡沫破裂之后-一蹶不振-郁金香泡沫-有的泡沫破裂之后-却逆势上扬-互联网-比特币泡沫-区别在哪里","link":"#有的泡沫破裂之后-一蹶不振-郁金香泡沫-有的泡沫破裂之后-却逆势上扬-互联网-比特币泡沫-区别在哪里","children":[]},{"level":2,"title":"宏观观察的方法论入手，思考BOX组合标的的选择原则。","slug":"宏观观察的方法论入手-思考box组合标的的选择原则。","link":"#宏观观察的方法论入手-思考box组合标的的选择原则。","children":[]},{"level":2,"title":"和其他假把式相比，为什么说定投策略是最佳的不战而胜的策略？","slug":"和其他假把式相比-为什么说定投策略是最佳的不战而胜的策略","link":"#和其他假把式相比-为什么说定投策略是最佳的不战而胜的策略","children":[]},{"level":2,"title":"为什么避开股市里最糟糕的日子不现实且不是好策略？","slug":"为什么避开股市里最糟糕的日子不现实且不是好策略","link":"#为什么避开股市里最糟糕的日子不现实且不是好策略","children":[]},{"level":2,"title":"为什么投资不是普通生意？","slug":"为什么投资不是普通生意","link":"#为什么投资不是普通生意","children":[]},{"level":2,"title":"如何提升自己的场外持续赚钱能力？","slug":"如何提升自己的场外持续赚钱能力","link":"#如何提升自己的场外持续赚钱能力","children":[]},{"level":2,"title":"定投执行有几个阶段？各个阶段遇到的问题是什么？该如何应对？","slug":"定投执行有几个阶段-各个阶段遇到的问题是什么-该如何应对","link":"#定投执行有几个阶段-各个阶段遇到的问题是什么-该如何应对","children":[]},{"level":2,"title":"我们究竟有多不靠谱","slug":"我们究竟有多不靠谱","link":"#我们究竟有多不靠谱","children":[]},{"level":2,"title":"你并不是自己的敌人，你要好好做自己的朋友，怎么做自己的朋友呢？","slug":"你并不是自己的敌人-你要好好做自己的朋友-怎么做自己的朋友呢","link":"#你并不是自己的敌人-你要好好做自己的朋友-怎么做自己的朋友呢","children":[]},{"level":2,"title":"最惊人的镜像效应究竟是什么造成的？","slug":"最惊人的镜像效应究竟是什么造成的","link":"#最惊人的镜像效应究竟是什么造成的","children":[]},{"level":2,"title":"为什么知道和做到之间的距离很长？","slug":"为什么知道和做到之间的距离很长","link":"#为什么知道和做到之间的距离很长","children":[]},{"level":2,"title":"投资领域，主动和被动的边界在哪里？","slug":"投资领域-主动和被动的边界在哪里","link":"#投资领域-主动和被动的边界在哪里","children":[]}],"relativePath":"posts/homework/126.md","filePath":"posts/homework/126.md"}'),r={name:"posts/homework/126.md"};function h(o,a,n,d,s,c){return l(),t("div",null,[...a[0]||(a[0]=[i('<p>2月定投课堂读书会的书目是《定投改变命运》的中英文版本。</p><h1 id="第一周" tabindex="-1">第一周 <a class="header-anchor" href="#第一周" aria-label="Permalink to &quot;第一周&quot;">​</a></h1><h2 id="定投策略为什么有效" tabindex="-1">定投策略为什么有效？ <a class="header-anchor" href="#定投策略为什么有效" aria-label="Permalink to &quot;定投策略为什么有效？&quot;">​</a></h2><p>选择的定投的标的是一个长期成长的标的，牛短熊长，利润来自漫长的熊市。</p><h2 id="长期究竟有多长" tabindex="-1">长期究竟有多长？ <a class="header-anchor" href="#长期究竟有多长" aria-label="Permalink to &quot;长期究竟有多长？&quot;">​</a></h2><p>长期是两个大周期，包含一个下降的B阶段和一个上升的A阶段</p><h2 id="为什么一定要用钱赚钱" tabindex="-1">为什么一定要用钱赚钱？ <a class="header-anchor" href="#为什么一定要用钱赚钱" aria-label="Permalink to &quot;为什么一定要用钱赚钱？&quot;">​</a></h2><p>人的寿命是有限的，可供出售的时间就更加有限了。如果做了正确的投资，金钱永不眠，它一天24小时，一年365天，每分每秒都在为你赚钱。</p><h2 id="我们到底在用什么定投" tabindex="-1">我们到底在用什么定投？ <a class="header-anchor" href="#我们到底在用什么定投" aria-label="Permalink to &quot;我们到底在用什么定投？&quot;">​</a></h2><p>我们在用钱和时间定投，时间是指数函数的指数部分。</p><h2 id="为什么定投策略无需再次改良" tabindex="-1">为什么定投策略无需再次改良？ <a class="header-anchor" href="#为什么定投策略无需再次改良" aria-label="Permalink to &quot;为什么定投策略无需再次改良？&quot;">​</a></h2><p>价格波动是滞后判断的表现，短期的价格无法预测，如果标的是一只成长的，现在每天的价格都很低。</p><p>最近收听“无人知晓”，其中一期说到，「我们需要简单稳妥的体系，控制情绪的能力，不要让情绪破坏这个体系」。</p><p>定投已经是一个足够简单的体系，所谓的“改良”会引发不必要的情绪，这种情绪足以摧毁这个体系。</p><p>我们时常可以听到的，因为忘了账号密码，因为去世，因为进了监狱，股市里面的钱反而大赚一笔的。过多的操作反而血本无归。</p><h1 id="第二周" tabindex="-1">第二周 <a class="header-anchor" href="#第二周" aria-label="Permalink to &quot;第二周&quot;">​</a></h1><h2 id="可以盲从的投资建议是什么" tabindex="-1">可以盲从的投资建议是什么？ <a class="header-anchor" href="#可以盲从的投资建议是什么" aria-label="Permalink to &quot;可以盲从的投资建议是什么？&quot;">​</a></h2><p>盲从那咩已经展示长期成功业绩的真正成功投资者的建议，这些建议既正确又免费。越是拥有长期成功经验的投资者也是开诚布公。</p><h2 id="为什么趋势投资优于价值投资" tabindex="-1">为什么趋势投资优于价值投资 <a class="header-anchor" href="#为什么趋势投资优于价值投资" aria-label="Permalink to &quot;为什么趋势投资优于价值投资&quot;">​</a></h2><p>价值投资需要投资者时时关注现在的价格和未来的价值，关注现在的价格容易让人短视，而评估未来一段时间的价值是很难的事情，价值投资不容易做到。</p><p>趋势投资从长期视角出发，以长期持续成长来筛选标的，眼前的价值和价格直接的差距变得不那么重要。</p><h2 id="选择长期-两个大周期-定投的标的的方法论是什么" tabindex="-1">选择长期（两个大周期）定投的标的的方法论是什么？ <a class="header-anchor" href="#选择长期-两个大周期-定投的标的的方法论是什么" aria-label="Permalink to &quot;选择长期（两个大周期）定投的标的的方法论是什么？&quot;">​</a></h2><p>看标的是否可以长期持续的成长，标的是否是成长最快的。</p><h2 id="有的泡沫破裂之后-一蹶不振-郁金香泡沫-有的泡沫破裂之后-却逆势上扬-互联网-比特币泡沫-区别在哪里" tabindex="-1">有的泡沫破裂之后，一蹶不振（郁金香泡沫），有的泡沫破裂之后，却逆势上扬（互联网，比特币泡沫）区别在哪里？ <a class="header-anchor" href="#有的泡沫破裂之后-一蹶不振-郁金香泡沫-有的泡沫破裂之后-却逆势上扬-互联网-比特币泡沫-区别在哪里" aria-label="Permalink to &quot;有的泡沫破裂之后，一蹶不振（郁金香泡沫），有的泡沫破裂之后，却逆势上扬（互联网，比特币泡沫）区别在哪里？&quot;">​</a></h2><p>最主要的区别就是泡沫所代表的标的是否有长期价值，能否长期持续成长。「变革曲线」很好的解释了趋势发展必然经历泡沫，对于长期有价值的标的，泡沫破裂反而是定投者入场的好时机。</p><p>人生不如意十有八九，是安慰人时经常用的话。但在不如意的时候，有的人从此一蹶不振，而有的人却是东山再起。史玉柱，褚时健的传奇故事我们并不陌生，这些人，他们在最坏的日子没有输掉的筹码是什么呢？</p><h2 id="宏观观察的方法论入手-思考box组合标的的选择原则。" tabindex="-1">宏观观察的方法论入手，思考BOX组合标的的选择原则。 <a class="header-anchor" href="#宏观观察的方法论入手-思考box组合标的的选择原则。" aria-label="Permalink to &quot;宏观观察的方法论入手，思考BOX组合标的的选择原则。&quot;">​</a></h2><p>选择方法，从全球，到区域，到行业，再到局部的头部，原则符合行业发展的趋势，选发展最快的。区块链是目前发展最快的行业，BOX是一个组合，涵盖了区块链中发展最快的几个标的，更重要的是这些标的符合行业发展的趋势，可信账簿（BTC）-&gt;可信代码（ETH/EOS）-&gt;可信执行环境（XIN）-&gt;可信硬件（MOB）。</p><h1 id="第三周" tabindex="-1">第三周 <a class="header-anchor" href="#第三周" aria-label="Permalink to &quot;第三周&quot;">​</a></h1><h2 id="和其他假把式相比-为什么说定投策略是最佳的不战而胜的策略" tabindex="-1">和其他假把式相比，为什么说定投策略是最佳的不战而胜的策略？ <a class="header-anchor" href="#和其他假把式相比-为什么说定投策略是最佳的不战而胜的策略" aria-label="Permalink to &quot;和其他假把式相比，为什么说定投策略是最佳的不战而胜的策略？&quot;">​</a></h2><p>高频的交易不仅降低了成功概率，同时增加了交易成本，而且花费大量的时间和精力。</p><p>定投策略只有一个动作买，这样可以降低出错的可能。</p><h2 id="为什么避开股市里最糟糕的日子不现实且不是好策略" tabindex="-1">为什么避开股市里最糟糕的日子不现实且不是好策略？ <a class="header-anchor" href="#为什么避开股市里最糟糕的日子不现实且不是好策略" aria-label="Permalink to &quot;为什么避开股市里最糟糕的日子不现实且不是好策略？&quot;">​</a></h2><p>股市的价格无法预测，股市里的好日子紧随糟糕日子其后，避开了好日子，也就避开了好日子。</p><h2 id="为什么投资不是普通生意" tabindex="-1">为什么投资不是普通生意？ <a class="header-anchor" href="#为什么投资不是普通生意" aria-label="Permalink to &quot;为什么投资不是普通生意？&quot;">​</a></h2><p>投资的钱不应该有成本，有期限的钱会让好投资变糟糕。</p><h2 id="如何提升自己的场外持续赚钱能力" tabindex="-1">如何提升自己的场外持续赚钱能力？ <a class="header-anchor" href="#如何提升自己的场外持续赚钱能力" aria-label="Permalink to &quot;如何提升自己的场外持续赚钱能力？&quot;">​</a></h2><p>把自己的一份时间销售多次，销售——把别人的时间销售多次，提高自己的可合作性。</p><h2 id="定投执行有几个阶段-各个阶段遇到的问题是什么-该如何应对" tabindex="-1">定投执行有几个阶段？各个阶段遇到的问题是什么？该如何应对？ <a class="header-anchor" href="#定投执行有几个阶段-各个阶段遇到的问题是什么-该如何应对" aria-label="Permalink to &quot;定投执行有几个阶段？各个阶段遇到的问题是什么？该如何应对？&quot;">​</a></h2><p>第一个下降阶段，面对损失的时候想做出改变。观察别人的错误，写下自己的想法，但什么也不做。</p><p>第一个上升阶段，世界充满噪音，感觉自己变聪明了。场内什么也不做，场外努力赚钱。</p><p>第二个下降阶段，损失的波动很大，总想着离场换钱。放松心态，每一个低谷都是新的起点。。</p><p>第二个上升阶段，赚了很多钱但没有找到知道自己持续努力的目标。用定投的方式持续的学习和成长。</p><h1 id="第四周" tabindex="-1">第四周 <a class="header-anchor" href="#第四周" aria-label="Permalink to &quot;第四周&quot;">​</a></h1><h2 id="我们究竟有多不靠谱" tabindex="-1">我们究竟有多不靠谱 <a class="header-anchor" href="#我们究竟有多不靠谱" aria-label="Permalink to &quot;我们究竟有多不靠谱&quot;">​</a></h2><p>我们不靠谱的地方太多了，已知的普遍心理偏差就有137个，以后会发现更多。</p><blockquote><p>过度自信会让我们出错，维护自我脸面会让我们出错，谈话方式会让我们出错，情绪激动会让我们出错，休息不足会让我们出错，体内糖分减少会让我们出错，甚至阳光明媚也会导致我们更容易出错；不仅如此，我们对风险的认知永远对不上号；我们对收益的认知总是非常扭曲；手中信息太少我们会出错，手中信息太多我们更会出错……而这个列表事实上可以没完没了。更为糟糕的是，在明明知道道理的情况下，我们还“就是控制不住自己”，在明明已经被证明错了的情况下，我们还可能爆发逆火……</p></blockquote><h2 id="你并不是自己的敌人-你要好好做自己的朋友-怎么做自己的朋友呢" tabindex="-1">你并不是自己的敌人，你要好好做自己的朋友，怎么做自己的朋友呢？ <a class="header-anchor" href="#你并不是自己的敌人-你要好好做自己的朋友-怎么做自己的朋友呢" aria-label="Permalink to &quot;你并不是自己的敌人，你要好好做自己的朋友，怎么做自己的朋友呢？&quot;">​</a></h2><p>当事情发生的时候”让子弹飞一会“，对自己多一点耐心，处理事情的时候，黑马，白马和车夫都处理一便。</p><h2 id="最惊人的镜像效应究竟是什么造成的" tabindex="-1">最惊人的镜像效应究竟是什么造成的？ <a class="header-anchor" href="#最惊人的镜像效应究竟是什么造成的" aria-label="Permalink to &quot;最惊人的镜像效应究竟是什么造成的？&quot;">​</a></h2><p>最惊人的镜像效应是长期观念。</p><ul><li>一旦你想尽一切办法启用长期观念，最终你会发现“宏观观察的不同”和“宏观观察的简单”，然后你会惊讶于这样一个事实：</li><li>越重要的问题越容易解决，最重要的问题解决起来最简单——可人们偏偏要把所有的智慧都在那些既复杂又无关紧要的地方。</li></ul><p>一开始没有解决最重要的问题，导致问题之树盘根错节的生长。</p><h2 id="为什么知道和做到之间的距离很长" tabindex="-1">为什么知道和做到之间的距离很长？ <a class="header-anchor" href="#为什么知道和做到之间的距离很长" aria-label="Permalink to &quot;为什么知道和做到之间的距离很长？&quot;">​</a></h2><p>人生来不靠谱，天生缺少长期观念，没有区分主动和被动的边界。做决策时缺乏经验，即便是简单的知识，也需要长时间才能不出错，对于更重要的活动，需要边做边学。</p><h2 id="投资领域-主动和被动的边界在哪里" tabindex="-1">投资领域，主动和被动的边界在哪里？ <a class="header-anchor" href="#投资领域-主动和被动的边界在哪里" aria-label="Permalink to &quot;投资领域，主动和被动的边界在哪里？&quot;">​</a></h2><p>投资前主动的认真的选择好的标的——长期持续成长的标的，投资后保持持续定投，安心场外赚钱。</p>',57)])])}const b=e(r,[["render",h]]);export{u as __pageData,b as default};
